# =====================================================================================
# Apply-Session2.ps1 - MetabolicInt Session 2 ONE-FILE installer
#
# All 16 Session 2 patches are EMBEDDED in this file (base64, SHA-256 verified
# before anything is touched). One successful download = complete install.
# The series lands as 16 separate commits on top of main @ 25ed988 via
# git am --3way --ignore-whitespace. Never squashed. Merge-commit PRs welcome.
#
# HOW TO RUN (from the folder containing this file, e.g. C:\Users\you\Downloads):
#   powershell -ExecutionPolicy Bypass -File .\Apply-Session2.ps1
#   It finds your repo, shows a plan, asks y/n, then applies.
#
# OPTIONS:
#   -RepoPath "C:\path\to\MetabolicInt"   skip repo auto-discovery
#   -Yes                                  skip the y/n confirmation
#   -VerifyOnly                           check your Session 2 downloads
#                                         (existence + size + SHA-256), then exit
#   -VerifyOnly -Folder "C:\some\folder"  ...against a specific folder
#   -ExtractOnly "C:\somewhere"           write the 16 .patch files + checksums.txt
#                                         there, no git involved
#
# SAFETY: refuses to run unless branch=main, working tree clean (untracked files
# are fine), and the base commit 25ed988 exists. Idempotent: exits 0 if the
# series is already applied. Resumes a partial series at the right patch.
# =====================================================================================
param(
    [string]$RepoPath = "",
    [string]$Folder = "",
    [string]$ExtractOnly = "",
    [switch]$VerifyOnly,
    [switch]$Yes
)

$ErrorActionPreference = 'Stop'
$BaseSha = '25ed98888ee8a7daac07190956decf31f6e533a6'
$BaseRef = '25ed988'
$SeriesCount = 16

