# === helpers =======================================================================
function Get-Sha256Bytes {
    param([byte[]]$Bytes)
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace('-','').ToLower() }
    finally { $sha.Dispose() }
}

function Invoke-Git {
    param([string]$Repo, [string[]]$GitArgs)
    $prev = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    try {
        $out = & git -C $Repo @GitArgs 2>&1
        $code = $LASTEXITCODE
    } finally { $ErrorActionPreference = $prev }
    $lines = @($out | ForEach-Object { $_.ToString() })
    return @{ Exit = $code; Lines = $lines; Text = ($lines -join "`n") }
}

# === mode: -VerifyOnly (check downloads, then exit) ================================
if ($VerifyOnly) {
    if ($Folder -eq '') { $Folder = $PSScriptRoot }
    if (-not (Test-Path -LiteralPath $Folder -PathType Container)) {
        Write-Host "Folder not found: $Folder" -ForegroundColor Red
        exit 2
    }
    $Folder = (Resolve-Path -LiteralPath $Folder).Path
    $allFiles = @(Get-ChildItem -LiteralPath $Folder -Recurse -File -ErrorAction SilentlyContinue)
    $byName = @{}
    foreach ($f in $allFiles) {
        if (-not $byName.ContainsKey($f.Name)) { $byName[$f.Name] = @() }
        $byName[$f.Name] += $f.FullName
    }
    $ok = 0; $missing = @(); $sizeBad = @(); $hashBad = @(); $emptySource = 0
    Write-Host ""
    Write-Host "Verifying $($DownloadsManifest.Count) files against folder: $Folder" -ForegroundColor Cyan
    Write-Host ("-" * 78)
    foreach ($line in $DownloadsManifest) {
        $parts = $line.Split('|')
        $sha = $parts[0]
        $bytes = [int64]$parts[1]
        $rel = $parts[2]
        $name = [System.IO.Path]::GetFileName($rel)
        if ($bytes -eq 0) {
            Write-Host "[EMPTY-SRC] $rel - 0-byte source, not downloadable by design" -ForegroundColor DarkGray
            $emptySource++
            continue
        }
        $path = Join-Path $Folder $rel
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
            if ($byName.ContainsKey($name) -and $byName[$name].Count -gt 0) {
                $path = $byName[$name][0]
            } else {
                Write-Host "[MISSING]   $rel" -ForegroundColor Yellow
                $missing += $rel
                continue
            }
        }
        $actual = (Get-Item -LiteralPath $path).Length
        if ($actual -ne $bytes) {
            Write-Host "[SIZE BAD]  $rel - expected $bytes bytes, got $actual" -ForegroundColor Red
            $sizeBad += $rel
            continue
        }
        $actualSha = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLower()
        if ($actualSha -ne $sha) {
            Write-Host "[HASH BAD]  $rel - download corrupted (SHA-256 mismatch)" -ForegroundColor Red
            $hashBad += $rel
            continue
        }
        Write-Host "[OK]        $rel" -ForegroundColor Green
        $ok++
    }
    Write-Host ("-" * 78)
    $checked = $DownloadsManifest.Count - $emptySource
    Write-Host ("Summary: {0} OK | {1} missing | {2} size-mismatch | {3} hash-mismatch | {4} empty-source (expected)" -f $ok, $missing.Count, $sizeBad.Count, $hashBad.Count, $emptySource)
    if ($missing.Count -gt 0) {
        Write-Host ""
        Write-Host "Missing files (re-download these):" -ForegroundColor Yellow
        foreach ($mm in $missing) { Write-Host "  - $mm" }
    }
    if ($sizeBad.Count -gt 0 -or $hashBad.Count -gt 0) {
        Write-Host ""
        Write-Host "Corrupted files (re-download these):" -ForegroundColor Red
        foreach ($bb in @($sizeBad + $hashBad)) { Write-Host "  - $bb" }
    }
    if (($ok -eq $checked) -and $checked -gt 0) {
        Write-Host ""
        Write-Host "ALL DOWNLOADS VERIFIED SUCCESSFULLY." -ForegroundColor Green
        exit 0
    }
    exit 1
}

# === step 1: verify the embedded payload ===========================================
Write-Host "Step 1: verifying embedded payload integrity (16 patches)..." -ForegroundColor Cyan
$meta = @{}
$ExpectedSubjects = @{}
foreach ($line in $PatchMeta) {
    $p = $line.Split('|')
    $meta[$p[2]] = @{ Sha = $p[0]; Bytes = [int64]$p[1] }
    $ExpectedSubjects[[int]$p[2].Substring(0,4)] = $p[3]
}
$decoded = @{}
$payloadBad = @()
foreach ($key in ($Payload.Keys | Sort-Object)) {
    try { $bytes = [Convert]::FromBase64String($Payload[$key]) }
    catch { Write-Host "  [DECODE FAIL] $key" -ForegroundColor Red; $payloadBad += $key; continue }
    if ($bytes.Length -ne $meta[$key].Bytes) {
        Write-Host "  [SIZE BAD]   $key - expected $($meta[$key].Bytes) bytes, decoded $($bytes.Length)" -ForegroundColor Red
        $payloadBad += $key; continue
    }
    if ((Get-Sha256Bytes $bytes) -ne $meta[$key].Sha) {
        Write-Host "  [HASH BAD]   $key - SHA-256 mismatch" -ForegroundColor Red
        $payloadBad += $key; continue
    }
    $decoded[$key] = $bytes
}
if ($payloadBad.Count -gt 0) {
    Write-Host ""
    Write-Host "This script file is damaged (bad download?). Nothing was changed." -ForegroundColor Red
    Write-Host "Re-download Apply-Session2.ps1 and run it again."
    exit 1
}
Write-Host "  all 16 patches verified (SHA-256 OK)." -ForegroundColor Green
$AllNames = @($Payload.Keys | Sort-Object)

# === mode: -ExtractOnly (write patch files, no git) ================================
if ($ExtractOnly -ne '') {
    New-Item -ItemType Directory -Force -Path $ExtractOnly | Out-Null
    $checksums = @()
    foreach ($name in $AllNames) {
        $p = Join-Path $ExtractOnly $name
        [System.IO.File]::WriteAllBytes($p, $decoded[$name])
        $checksums += "$($meta[$name].Sha)  $name"
        Write-Host "  wrote $p"
    }
    [System.IO.File]::WriteAllLines((Join-Path $ExtractOnly 'checksums.txt'), $checksums)
    Write-Host "Done. checksums.txt written alongside." -ForegroundColor Green
    exit 0
}

# === step 2: locate the repo =======================================================
Write-Host ""
Write-Host "Step 2: locating your MetabolicInt checkout..." -ForegroundColor Cyan
function Test-IsRepo([string]$p) {
    return (Test-Path -LiteralPath (Join-Path $p '.git')) -and
           (Test-Path -LiteralPath (Join-Path $p 'apps\web\package.json')) -and
           (Test-Path -LiteralPath (Join-Path $p 'packages\engine'))
}
if ($RepoPath -ne '') {
    if (-not (Test-IsRepo $RepoPath)) {
        Write-Host "Not a MetabolicInt checkout: $RepoPath" -ForegroundColor Red
        Write-Host "Expected layout: .git + apps\web + packages\engine"
        exit 2
    }
    $Repo = (Resolve-Path -LiteralPath $RepoPath).Path
} else {
    $probe = @(
        (Join-Path $PSScriptRoot 'MetabolicInt'),
        (Join-Path $env:USERPROFILE 'MetabolicInt'),
        (Join-Path $env:USERPROFILE 'Desktop\MetabolicInt'),
        (Join-Path $env:USERPROFILE 'Documents\MetabolicInt'),
        (Join-Path $env:USERPROFILE 'Documents\GitHub\MetabolicInt'),
        (Join-Path $env:USERPROFILE 'source\repos\MetabolicInt'),
        'C:\dev\MetabolicInt', 'C:\code\MetabolicInt', 'C:\repos\MetabolicInt', 'C:\projects\MetabolicInt',
        'D:\MetabolicInt', 'D:\dev\MetabolicInt', 'D:\code\MetabolicInt', 'D:\projects\MetabolicInt'
    )
    $found = @($probe | Where-Object { Test-IsRepo $_ } | ForEach-Object { (Resolve-Path -LiteralPath $_).Path } | Select-Object -Unique)
    if ($found.Count -eq 1) {
        $Repo = $found[0]
    } elseif ($found.Count -gt 1) {
        Write-Host "Found more than one MetabolicInt checkout:" -ForegroundColor Yellow
        for ($i = 0; $i -lt $found.Count; $i++) { Write-Host ("  [{0}] {1}" -f ($i + 1), $found[$i]) }
        $sel = Read-Host "Which one? (1-$($found.Count))"
        $n = 0
        if ([int]::TryParse($sel, [ref]$n) -and $n -ge 1 -and $n -le $found.Count) { $Repo = $found[$n - 1] } else { exit 2 }
    } else {
        Write-Host "No MetabolicInt checkout found in the usual places." -ForegroundColor Yellow
        $ans = Read-Host "Paste the full path to your MetabolicInt repo (Enter = cancel)"
        if ($ans -eq '' -or -not (Test-IsRepo $ans)) {
            Write-Host "Cancelled. If you have not cloned it yet, first run:" -ForegroundColor Yellow
            Write-Host "  git clone https://github.com/tradaninik/MetabolicInt   (check your exact repo URL on GitHub)"
            exit 2
        }
        $Repo = (Resolve-Path -LiteralPath $ans).Path
    }
}
Write-Host "  Repo: $Repo" -ForegroundColor Green

# === step 3: pre-flight checks =====================================================
Write-Host ""
Write-Host "Step 3: pre-flight checks..." -ForegroundColor Cyan
if (-not (Get-Command git -ErrorAction SilentlyContinue)) {
    Write-Host "git not found on PATH. Install Git for Windows first." -ForegroundColor Red
    exit 2
}
$br = Invoke-Git $Repo @('rev-parse', '--abbrev-ref', 'HEAD')
if ($br.Exit -ne 0) { Write-Host "Could not read the branch: $($br.Text)" -ForegroundColor Red; exit 2 }
if ($br.Lines[0] -ne 'main') {
    Write-Host "Current branch is '$($br.Lines[0])' but this series applies to 'main'." -ForegroundColor Red
    Write-Host "Run:  git -C `"$Repo`" checkout main"
    exit 2
}
$st = Invoke-Git $Repo @('status', '--porcelain')
$dirty = @($st.Lines | Where-Object { $_ -ne '' -and $_ -notmatch '^\?\?' })
if ($dirty.Count -gt 0) {
    Write-Host "Working tree has uncommitted changes. Commit or stash them first:" -ForegroundColor Red
    $dirty | Select-Object -First 10 | ForEach-Object { Write-Host "  $_" }
    exit 2
}
$baseChk = Invoke-Git $Repo @('rev-parse', '--verify', "${BaseSha}^{commit}")
if ($baseChk.Exit -ne 0) {
    Write-Host "Base commit $BaseRef not found in this repo." -ForegroundColor Red
    Write-Host "Your main may not include the session-1 PR merge yet. Run:  git -C `"$Repo`" pull"
    exit 2
}
$behind = Invoke-Git $Repo @('merge-base', '--is-ancestor', 'HEAD', $BaseSha)
if ($behind.Exit -eq 0) {
    Write-Host "Your main is BEHIND $BaseRef (the session-1 merge). Run:  git -C `"$Repo`" pull" -ForegroundColor Red
    exit 2
}
$cnt = Invoke-Git $Repo @('rev-list', '--count', "${BaseSha}..HEAD")
$nPast = [int]$cnt.Lines[0]
$subj = Invoke-Git $Repo @('log', '--format=%s', '--reverse', "${BaseSha}..HEAD")
$subjects = @($subj.Lines | Where-Object { $_ -ne '' })
$matchesSeries = ($subjects.Count -le $SeriesCount)
if ($matchesSeries) {
    for ($i = 0; $i -lt $subjects.Count; $i++) {
        if ($subjects[$i] -ne $ExpectedSubjects[($i + 1)]) { $matchesSeries = $false; break }
    }
}
$applyFrom = 1
if ($matchesSeries -and $subjects.Count -eq $SeriesCount) {
    Write-Host "  Session 2 is ALREADY applied (all 16 commits present). Nothing to do." -ForegroundColor Green
    exit 0
} elseif ($matchesSeries -and $subjects.Count -gt 0) {
    $applyFrom = $subjects.Count + 1
    Write-Host "  Partial series detected: $(${subjects}.Count) of 16 applied. Will resume at patch $applyFrom." -ForegroundColor Yellow
} elseif ($nPast -gt 0) {
    Write-Host "  main is $nPast commit(s) past $BaseRef and they are NOT this series:" -ForegroundColor Yellow
    $subjects | Select-Object -Last 8 | ForEach-Object { Write-Host "    $_" -ForegroundColor DarkGray }
    if (-not $Yes) {
        $ans = Read-Host "  Attempt full apply anyway? git am --3way will try to merge (y/n)"
        if ($ans.Trim().ToLower() -notin @('y','yes')) { Write-Host "Cancelled - nothing was changed."; exit 0 }
    } else {
        Write-Host "  -Yes given: attempting full apply." -ForegroundColor Yellow
    }
} else {
    Write-Host "  Clean base: main @ $BaseRef." -ForegroundColor Green
}

$todo = @($AllNames | Where-Object { [int]($_.Substring(0,4)) -ge $applyFrom })
if ($todo.Count -eq 0) { Write-Host "Nothing to apply."; exit 0 }

# === confirm =======================================================================
Write-Host ""
Write-Host "Plan:" -ForegroundColor White
Write-Host "  Repo:      $Repo"
Write-Host "  Base:      $BaseRef (session-1 PR merge)"
Write-Host "  Applying:  $($todo.Count) patch(es): $($todo[0]) .. $($todo[$todo.Count - 1])"
Write-Host "  Result:    16 separate commits on main (never squashed)"
if (-not $Yes) {
    $ans = Read-Host "Proceed? (y/n)"
    if ($ans.Trim().ToLower() -notin @('y','yes')) { Write-Host "Cancelled - nothing was changed."; exit 0 }
}

# === step 4: write patches to temp + verify ========================================
$patchDir = Join-Path $env:TEMP ("mi-session2-patches-" + (Get-Date -Format 'yyyyMMddHHmmss'))
New-Item -ItemType Directory -Path $patchDir | Out-Null
$patchFiles = @()
foreach ($name in $todo) {
    $p = Join-Path $patchDir $name
    [System.IO.File]::WriteAllBytes($p, $decoded[$name])
    $shaNow = (Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLower()
    if ($shaNow -ne $meta[$name].Sha) { Write-Host "Post-write verification failed: $name" -ForegroundColor Red; exit 1 }
    $patchFiles += $p
}
Write-Host ""
Write-Host "Step 4: applying $($patchFiles.Count) patches with git am --3way --ignore-whitespace..." -ForegroundColor Cyan
$am = Invoke-Git $Repo (@('am', '--3way', '--ignore-whitespace') + $patchFiles)
foreach ($l in $am.Lines) { Write-Host "  $l" }
if ($am.Exit -ne 0) {
    Write-Host ""
    Write-Host "git am FAILED (exit $($am.Exit))." -ForegroundColor Red
    Write-Host "Roll back cleanly with:  git -C `"$Repo`" am --abort"
    Write-Host "Then fix the issue above and re-run this script."
    exit 1
}

# === done + next steps ==============================================================
$cnt2 = (Invoke-Git $Repo @('rev-list', '--count', "${BaseSha}..HEAD")).Lines[0]
Write-Host ""
Write-Host "Applied. main is now $cnt2 commit(s) past $BaseRef (16 = complete)." -ForegroundColor Green
$log = Invoke-Git $Repo @('log', '--oneline', '-17')
foreach ($l in $log.Lines) { Write-Host "  $l" }
Write-Host ""
Write-Host "Next steps - run from the repo root:  cd `"$Repo`"" -ForegroundColor Cyan
Write-Host "  1) npm ci"
Write-Host "  2) copy apps\web\.env.example apps\web\.env     (skip if .env already exists)"
Write-Host "  3) npm run db:push        (local SQLite; optional demo data: npm run db:seed)"
Write-Host "  4) npm test               expect: 619 passed + 3 skipped (51 files)"
Write-Host "  5) npx tsc --noEmit -p apps/web   and   -p packages/engine   and   -p packages/food-db   (all silent)"
Write-Host "  6) npm run lint           expect: 0 problems"
Write-Host "  7) npm run build          expect: Compiled successfully, 56 pages"
Write-Host "  8) npm run dev            then open http://localhost:3000"
Write-Host ""
Write-Host "Quick smoke checks: dashboard = mockup v1 layout; Know Your Body tie shows"
Write-Host "'Vata-Pitta profile' with history; Settings has the Ayurveda off-switch."
Write-Host "(A few prisma 'no such table' lines during build on an empty DB are known noise.)"
exit 0
